    out += "\((request.allHTTPHeaderFields ?? [:]).sorted { $0.key < $1.key })\n" + String(decoding: request.httpBody ?? Data(), as: UTF8.self) + "\n"
    out += "\([429, 529, 500, 400].map(ClaudeDesigner.retryable)) \([ClaudeDesigner.delay(attempt: 0, retryAfter: "90"), ClaudeDesigner.delay(attempt: 1, retryAfter: nil)]) \(ClaudeDesigner.failure(400, "{\"error\":\"output_config.format not supported\"}", model: "m")) \(ClaudeDesigner.failure(400, "bad", model: "m"))\n"; let tmp = FileManager.default.temporaryDirectory.appending(path: "dock-\(UUID().uuidString)"), packs = root.appending(path: "Packs"); defer { try? FileManager.default.removeItem(at: tmp) }; let full = LocalPlaces(root: tmp.appending(path: "full")), bare = LocalPlaces(root: tmp.appending(path: "none")), held = FixedClaude(key: "k", model: "m", origin: .local), blank = FixedClaude(key: "", model: "m", origin: .local); full.prepare(); let rows = { (d: Dock) in d.check().map { "\($0.port.rawValue) \($0.state)" }.joined(separator: ",") }, docks = [Dock.local(packs: packs, places: full, claude: held), Dock.local(packs: packs, places: bare, claude: blank), Dock.local(packs: tmp, places: full, claude: FixedClaude(key: "k", model: "m"))]; let named = { (p: [String: String], n: String, t: String, v: [String]) in ExportName.make(project: p, number: n, trade: t, variants: v, now: Date(timeIntervalSince1970: 0), ext: "pdf") ?? "-" }; out += docks.map(rows).joined(separator: "\n") + "\n" + [named(["date": "21.10.2026", "status": "vorabzug"], "2026-001", "Elektro", ["A"]), named(["date": "5.3.2027", "status": "Vorplanung"], "2027-012", "", []), named(["status": "entwurf"], "2027-012", "", []), named(["status": "Vorplanung"], "", "", []), named(["date": "21.10.2026", "status": "Vorabzug"], "2026/001", "", ["A B", ""])].joined(separator: " ") + "\n"; out += "\(docks[0].stateURL(Spot(project: "2026-001", drawing: "Kueche", date: "211026", initials: "JB"))?.path.replacingOccurrences(of: tmp.path, with: "") ?? "-") \(docks[1].templates.packs(.ci).filter { !$0.name.hasPrefix("studio") }.map(\.name)) \(PackKind.allCases.map { k in docks[0].templates.packs(k).filter { !$